ALTER TABLE split."SplitExpenses"
ADD COLUMN IF NOT EXISTS "Notes" text NULL,
ADD COLUMN IF NOT EXISTS "ReceiptPath" text NULL;

CREATE TABLE IF NOT EXISTS split."SplitActivities" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SplitGroupId" integer NOT NULL,
    "ActorUserId" text NULL,
    "ActorName" text NOT NULL,
    "Type" text NOT NULL,
    "Message" text NOT NULL,
    "SplitExpenseId" integer NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL,
    CONSTRAINT "FK_SplitActivities_SplitGroups_SplitGroupId" FOREIGN KEY ("SplitGroupId")
        REFERENCES split."SplitGroups" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_SplitActivities_SplitGroupId_Id" ON split."SplitActivities" ("SplitGroupId", "Id");
